                return expanded, new_path

            for neighbor in self.get_neighbors(*current):
                if neighbor not in visited:
                    new_cost = cost + 1
                    heuristic = abs(neighbor[0] - self.end[0]) + abs(neighbor[1] - self.end[1])
                    frontier.put((new_cost + heuristic, neighbor, new_path))

            expanded += 1

