        self.nodes = nodes

    def find_node(self, id: int):
        for node in self.nodes:
            if node.id == id:
                return node

    def topological_sort(self) -> List[Node]:
        in_degree = {node.id: len(node.in_edges) for node in self.nodes}
        queue = [node for node in self.nodes if in_degree[node.id] == 0]
        result = []

        while queue:
            node = queue.pop(0)
            result.append(node)

            for neighbor_id in node.in_edges:
                in_degree[neighbor_id] -= 1
                if in_degree[neighbor_id] == 0:
                    queue.append(self.find_node(neighbor_id))

        if len(result) != len(self.nodes):
            raise RuntimeError("Graph contains a cycle")

        return result

