        assert src in self.nodes

        visited = []
        to_visit = []
        to_visit.append(src)

        while len(to_visit) != 0:
            first = to_visit.pop()
            if first in visited:
                continue
            for n in first.out_edges:
                to_visit.append(n)

            visited.append(first)

        return visited

    def strongly_connected_components(self) -> Dict[Node, int]:
        reversed_graph = self.reverse_edges()
        visited = [False] * len(self.nodes)
        stack = []
        component_id = 0
        component_map = {}

        def dfs(node):
            visited[self.nodes.index(node)] = True
            for neighbor in node.out_edges:
                if not visited[self.nodes.index(neighbor)]:
                    dfs(neighbor)
            stack.append(node)

        for node in self.nodes:
            if not visited[self.nodes.index(node)]:
                dfs(node)

        visited = [False] * len(self.nodes)

        def dfs_reversed(node):
            nonlocal component_id
            visited[reversed_graph.nodes.index(node)] = True
            component_map[node] = component_id
            for neighbor in node.in_edges:
                if not visited[reversed_graph.nodes.index(neighbor)]:
                    dfs_reversed(neighbor)

        while stack:
            node = stack.pop()
            if not visited[reversed_graph.nodes.index(node)]:
                dfs_reversed(node)
                component_id += 1

        return component_map
